def _validate_profile_thresholds(thresholds: Any) -> list:
    if not isinstance(thresholds, list):
        raise TypeError("thresholds must be a list")
    if len(thresholds) == 0:
        raise ValueError("thresholds must be non-empty")

    previous = None
    for index, threshold in enumerate(thresholds):
        if (
            not isinstance(threshold, (int, float))
            or isinstance(threshold, bool)
        ):
            raise TypeError(
                f"thresholds[{index}] must be a finite non-bool int or float"
            )
        if not _is_finite(threshold) or threshold < 0:
            raise ValueError(
                f"thresholds[{index}] must be finite and non-negative"
            )
        if previous is not None and not threshold > previous:
            raise ValueError("thresholds must be strictly increasing")
        previous = threshold

    return thresholds


def panel_stability_profile(
    items, configs, thresholds, *, minimum: int = 1
) -> dict:
    """Aggregate :func:`panel_stability` across a range of thresholds.

    ``items``, ``configs`` and ``minimum`` are validated exactly as in
    :func:`panel_stability`, which is run once per threshold as
    ``panel_stability(items, configs, minimum=minimum, threshold=t)``.
    ``thresholds`` must be a non-empty list whose entries are finite
    non-bool non-negative ints or floats in strictly increasing order.
    A wrong container or entry type raises ``TypeError``; an empty
    container, a non-finite or negative entry, or a non-increasing
    sequence raises ``ValueError``.

    The returned mapping uses the key order ``schema, thresholds,
    panels, data, coverage``; ``schema`` is
    ``climate-grid/ps-profile-v1``, ``thresholds`` is echoed
    unchanged and ``panels`` lists the item names in item order.
    ``data`` follows the pair, then group, then name order from the
    per-threshold results; each row uses the key order
    ``pair, group, name, first, stable`` where ``stable`` is a list
    of booleans in threshold order and ``first`` is the first
    threshold for which the row is stable, or ``None`` when it is
    stable for none of them.

    ``coverage`` follows threshold order; each row uses the key
    order ``threshold, stable, total, rate`` where ``stable`` is the
    number of stable ``data`` rows, ``total`` is the number of
    ``data`` rows and ``rate`` is ``stable / total``.  Every derived
    float is ``round(x, 12)`` with negative zero normalized to
    ``0.0``; a non-finite derived value raises ``ValueError``.  The
    inputs are not modified.
    """
    _validate_profile_thresholds(thresholds)

    results = [
        panel_stability(
            items, configs, minimum=minimum, threshold=threshold
        )
        for threshold in thresholds
    ]

    panels = results[0]["panels"]
    data_rows: list[dict] = []
    stable_counts = [0 for _threshold in thresholds]
    for row_index, first_row in enumerate(results[0]["data"]):
        stable_flags: list[bool] = []
        first = None
        for result_index, result in enumerate(results):
            is_stable = result["data"][row_index]["stable"]
            stable_flags.append(is_stable)
            if is_stable:
                stable_counts[result_index] += 1
                if first is None:
                    first = thresholds[result_index]

        data_rows.append(
            {
                "pair": first_row["pair"],
                "group": first_row["group"],
                "name": first_row["name"],
                "first": first,
                "stable": stable_flags,
            }
        )

    total = len(data_rows)
    coverage_rows: list[dict] = []
    for threshold, stable_count in zip(thresholds, stable_counts):
        rate = _round_output(stable_count / total)
        if not _is_finite(rate):
            raise ValueError("coverage derived statistics must be finite")
        coverage_rows.append(
            {
                "threshold": threshold,
                "stable": stable_count,
                "total": total,
                "rate": rate,
            }
        )

    return {
        "schema": _PANEL_STABILITY_PROFILE_SCHEMA,
        "thresholds": thresholds,
        "panels": panels,
        "data": data_rows,
        "coverage": coverage_rows,
    }


_PANEL_STABILITY_MINIMUM_PROFILE_SCHEMA = "climate-grid/ps-minimum-profile-v1"


def _validate_profile_minimums(minimums: Any) -> list:
    if not isinstance(minimums, list):
        raise TypeError("minimums must be a list")
    if len(minimums) == 0:
        raise ValueError("minimums must be non-empty")

    previous = None
    for index, minimum in enumerate(minimums):
        if not isinstance(minimum, int) or isinstance(minimum, bool):
            raise TypeError(f"minimums[{index}] must be a non-bool int")
        if minimum <= 0:
            raise ValueError(f"minimums[{index}] must be positive")
        if previous is not None and not minimum > previous:
            raise ValueError("minimums must be strictly increasing")
        previous = minimum

    return minimums


def minimum_profile(items, configs, thresholds, minimums) -> dict:
    """Aggregate :func:`panel_stability_profile` across minimum counts.

"""Validate a complete :func:`minimum_profile` result.

Returns the ``minimums``, ``thresholds`` and ``panels`` axes and
the ``data`` rows, checking the
``climate-grid/ps-minimum-profile-v1`` contract: key order, the
schema, the axes, one data row per minimum and each row's key order
``minimum, first_counts, never, stable_counts, rates, deltas``.
The first row's ``deltas`` is an all-``None`` list; every later
row's is its ``rates`` minus the previous row's at the same
position, rounded to 12 digits.  Counts are non-bool non-negative
ints and rates and deltas are finite floats rounded to 12 digits.
"""
if not isinstance(result, dict):
    raise TypeError(f"{where} must be a dict")
if tuple(result.keys()) != _COMPARE_MINIMUM_PROFILES_RESULT_KEYS:
    raise ValueError(
        f"{where} must have exactly the keys schema, minimums, "
        "thresholds, panels, data in order"
    )

schema = result["schema"]
if not isinstance(schema, str):
    raise TypeError(f"{where}.schema must be a str")
if schema != _PANEL_STABILITY_MINIMUM_PROFILE_SCHEMA:
    raise ValueError(
        f"{where}.schema must be "
        f"{_PANEL_STABILITY_MINIMUM_PROFILE_SCHEMA!r}"
    )

minimums = _validate_profile_minimums(result["minimums"])
thresholds = _validate_profile_thresholds(result["thresholds"])

panels = result["panels"]
if not isinstance(panels, list):
    raise TypeError(f"{where}.panels must be a list")
if len(panels) == 0:
    raise ValueError(f"{where}.panels must be non-empty")
seen_panels: set[str] = set()
for panel_index, panel in enumerate(panels):
    panel_where = f"{where}.panels[{panel_index}]"
    if not isinstance(panel, str):
        raise TypeError(f"{panel_where} must be a str")
    if panel == "":
        raise ValueError(f"{panel_where} must be non-empty")
    if panel in seen_panels:
        raise ValueError(f"duplicate {where}.panels entry: {panel!r}")
    seen_panels.add(panel)

data = result["data"]
if not isinstance(data, list):
    raise TypeError(f"{where}.data must be a list")
if len(data) != len(minimums):
    raise ValueError(
        f"{where}.data must contain exactly one row per minimum"
    )

n_thresholds = len(thresholds)
previous_rates: list | None = None
expected_total: int | None = None
for row_index, (row, minimum) in enumerate(zip(data, minimums)):
    row_where = f"{where}.data[{row_index}]"
    if not isinstance(row, dict):
        raise TypeError(f"{row_where} must be a dict")
    if tuple(row.keys()) != _COMPARE_MINIMUM_PROFILES_DATA_ROW_KEYS:
        raise ValueError(
            f"{row_where} must have exactly the keys minimum, "
            "first_counts, never, stable_counts, rates, deltas in order"
        )

    row_minimum = row["minimum"]
    if not isinstance(row_minimum, int) or isinstance(row_minimum, bool):
        raise TypeError(f"{row_where}.minimum must be a non-bool int")
    if row_minimum != minimum:
        raise ValueError(
            f"{row_where}.minimum must equal the corresponding "
            "minimums entry"
        )

    first_counts = row["first_counts"]
    if not isinstance(first_counts, list):
        raise TypeError(f"{row_where}.first_counts must be a list")
    if len(first_counts) != n_thresholds:
        raise ValueError(
            f"{row_where}.first_counts must contain one count per "
            "threshold"
        )
    for count_index, count in enumerate(first_counts):
        count_where = f"{row_where}.first_counts[{count_index}]"
        if not isinstance(count, int) or isinstance(count, bool):
            raise TypeError(f"{count_where} must be a non-bool int")
        if count < 0:
            raise ValueError(f"{count_where} must be non-negative")

    never = row["never"]
    if not isinstance(never, int) or isinstance(never, bool):
        raise TypeError(f"{row_where}.never must be a non-bool int")
    if never < 0:
        raise ValueError(f"{row_where}.never must be non-negative")
    total = never + sum(first_counts)
    if total == 0:
        raise ValueError(
            f"{row_where}: never plus first_counts must be positive"
        )
    if expected_total is None:
        expected_total = total
    elif total != expected_total:
        raise ValueError(
            f"{row_where}: every row must partition the same number "
            "of profile data rows"
        )

    stable_counts = row["stable_counts"]
    if not isinstance(stable_counts, list):
        raise TypeError(f"{row_where}.stable_counts must be a list")
    if len(stable_counts) != n_thresholds:
        raise ValueError(
            f"{row_where}.stable_counts must contain one count per "
            "threshold"
        )
